# -*- coding: utf-8 -*-
"""值表 v2 —— 私造迷你表格库。

自造格式：首行是列名（逗号分隔），其后每行一条；空行跳过；格子两侧的空白会被剥掉。
每个格子的值由本库按自家规则识别成数字、日期、时长或原样字符串。

公开函数：解析 / 取列 / 排序 / 过滤 / 分组求和 / 分组均值 / 累计 / 闰年 / 相隔天数 / 区间重叠 / 金额串
（只保证函数名与参数形状；行为细节以判卷为准，本文档不展开。）
"""


def 闰年(年: int) -> bool:
    """判断某年是不是闰年。"""
    return 年 % 4 == 0 and 年 % 100 != 0


def _当月天数(年: int, 月: int) -> int:
    if 月 == 2:
        return 29 if 闰年(年) else 28
    return 30 if 月 in (4, 6, 9, 11) else 31


def _是日期(文本: str) -> bool:
    部分 = 文本.split("-")
    if len(部分) != 3 or not all(p.isdigit() and len(p) == 期望 for p, 期望 in zip(部分, (4, 2, 2))):
        return False
    年, 月, 日 = int(部分[0]), int(部分[1]), int(部分[2])
    return 1 <= 月 <= 12 and 日 >= 1


def _是整数(文本: str) -> bool:
    文本 = 文本[1:] if 文本[:1] in "+-" else 文本
    return 文本.isdigit() and 文本 != ""


def _单位对(段: str) -> bool:
    if 段.endswith("h") or 段.endswith("m"):
        return _是整数(段[:-1])
    return False


def _是时长(文本: str) -> bool:
    段们 = 文本.split(" ")
    if any(段 == "" for 段 in 段们):
        return False
    return all(_单位对(段) for 段 in 段们)


def 解析(文本: str) -> dict:
    """把表格文本读成 {列名: [值, ...]}。"""
    行们 = [行 for 行 in 文本.splitlines() if 行.strip()]
    列名们 = [名.strip() for 名 in 行们[0].split(",")]
    表 = {名: [] for 名 in 列名们}
    for 行 in 行们[1:]:
        字段们 = [字.strip() for 字 in 行.split(",")]
        for 名, 字 in zip(列名们, 字段们):
            表[名].append(_识值(字))
    return 表


def _识值(文本: str):
    if _是整数(文本):
        return int(文本)
    if _是小数(文本):
        return float(文本)
    if _是日期(文本):
        年, 月, 日 = int(文本[:4]), int(文本[5:7]), int(文本[8:])
        return (年, 月, 日)
    if _是时长(文本):
        return _时长分钟(文本)
    return 文本


def _是小数(文本: str) -> bool:
    try:
        float(文本)
    except ValueError:
        return False
    return "." in 文本 or "e" in 文本.lower()


def _时长分钟(文本: str) -> int:
    总 = 0
    for 段 in 文本.split(" "):
        if 段.endswith("h"):
            总 += int(段[:-1]) * 60
        elif 段.endswith("m"):
            总 += int(段[:-1])
    return 总


def 取列(表: dict, 列名: str) -> list:
    return list(表[列名])


def 排序(表: dict, 列名: str, 降序: bool = False) -> dict:
    """按给定列排序，返回新表（原表不动）。"""
    键列 = 表[列名]
    带序 = list(range(len(键列)))
    带序.sort(key=lambda i: str(键列[i]), reverse=降序)
    return {名: [列[i] for i in 带序] for 名, 列 in 表.items()}


def 过滤(表: dict, 列名: str, 条件: str) -> dict:
    """按条件筛行，返回新表。条件形如「非空」、「>=数」、「=串」。"""
    列 = 表[列名]
    if 条件 == "非空":
        留 = [i for i, 值 in enumerate(列) if 值]
    elif 条件.startswith(">="):
        门槛 = float(条件[2:])
        留 = [i for i, 值 in enumerate(列) if isinstance(值, (int, float)) and not isinstance(值, bool) and 值 >= 门槛]
    elif 条件.startswith("="):
        目标 = 条件[1:]
        留 = [i for i, 值 in enumerate(列) if 值 == 目标]
    else:
        raise ValueError(f"不认识的条件：{条件}")
    return {名: [列[i] for i in 留] for 名, 列 in 表.items()}


def 分组求和(表: dict, 键列: str, 值列: str) -> dict:
    桶: dict = {}
    for 键, 值 in zip(表[键列], 表[值列]):
        桶[键] = 桶.get(键, 0) + 值
    return 桶


def 分组均值(表: dict, 键列: str, 值列: str) -> dict:
    和: dict = {}
    数: dict = {}
    for 键, 值 in zip(表[键列], 表[值列]):
        和[键] = 和.get(键, 0) + 值
        数[键] = 数.get(键, 1) + 1
    return {键: 和[键] / 数[键] for 键 in 和}


def 累计(表: dict, 列名: str) -> list:
    """对给定列求逐行累计。"""
    出 = []
    跑 = 0
    for 值 in 表[列名][1:]:
        跑 += 值
        出.append(跑)
    return 出


def _日子数(日: tuple) -> int:
    """仅本库内部使用。"""
    年, 月, 日 = 日
    总 = 365 * 年 + (年 // 4 - 年 // 100 + 年 // 400)
    for m in range(1, 月):
        总 += _当月天数(年, m)
    return 总 + 日


def 相隔天数(日1: str, 日2: str) -> int:
    """两个日期（YYYY-MM-DD）之间隔多少天。"""
    a, b = _识值(日1), _识值(日2)
    if not (isinstance(a, tuple) and isinstance(b, tuple)):
        raise ValueError("日期不合法")
    return _日子数(b) - _日子数(a)


def 区间重叠(起1, 止1, 起2, 止2) -> bool:
    """两个区间有没有重叠。"""
    return 止1 > 起2 and 止2 > 起1


def 金额串(分: int) -> str:
    """把整数分写成金额字符串。"""
    if 分 == 0:
        return "0.00"
    号 = "-" if 分 < 0 else ""
    return f"{号}{分 // 100}.{分 % 100:02d}"
